import sys

input = sys.stdin.read().split()
n = int(input[0])
m = int(input[1])
table = [[int(input[n * m + i * m + j]) for j in range(m)] for i in range(n)]

rows_to_flip = []
cols_to_flip = []

for i in range(n):
    if sum(table[i]) < 0:
        rows_to_flip.append(i + 1)
        for j in range(m):
            table[i][j] *= -1

for j in range(m):
    if sum(table[i][j] for i in range(n)) < 0:
        cols_to_flip.append(j + 1)
        for i in range(n):
            table[i][j] *= -1

print(len(rows_to_flip), ' '.join(map(str, rows_to_flip)))
print(len(cols_to_flip), ' '.join(map(str, cols_to_flip)))
